type ContentSecurityPolicyOptions = {
  apiUrl?: string;
  overlayWebSocketUrl?: string;
  development?: boolean;
};

function connectOrigin(value: string | undefined): string | null {
  if (!value) return null;
  try {
    const url = new URL(value);
    if (!["http:", "https:", "ws:", "wss:"].includes(url.protocol)) {
      return null;
    }
    return url.origin;
  } catch {
    return null;
  }
}

/** Build a per-request CSP. The nonce is generated by middleware, never input. */
export function buildContentSecurityPolicy(
  nonce: string,
  options: ContentSecurityPolicyOptions = {},
): string {
  if (!/^[A-Za-z0-9+/_=-]+$/.test(nonce)) {
    throw new Error("invalid CSP nonce");
  }

  const connectSources = new Set(["'self'"]);
  for (const candidate of [options.apiUrl, options.overlayWebSocketUrl]) {
    const origin = connectOrigin(candidate);
    if (origin) connectSources.add(origin);
  }

  const scriptSources = ["'self'", `'nonce-${nonce}'`, "'strict-dynamic'"];
  if (options.development) scriptSources.push("'unsafe-eval'");

  return [
    "default-src 'self'",
    `script-src ${scriptSources.join(" ")}`,
    "style-src 'self' 'unsafe-inline'",
    `connect-src ${[...connectSources].join(" ")}`,
    "img-src 'self' data: blob:",
    "font-src 'self' data:",
    "media-src 'self' blob:",
    "frame-src 'self'",
    "frame-ancestors 'none'",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
  ].join("; ");
}
